fn copy(a: &Vec<u64>) -> Vec<u64> {
    // Pre-allocate a new vector with the same length as `a`
    let mut b = Vec::with_capacity(a.len());
    // Push each element in order
    for &item in a.iter() {
        b.push(item);
    }
    b
}